func (c *Client) applyEditors(ctx context.Context, req *http.Request, additionalEditors []RequestEditorFn) error {
	for _, r := range c.RequestEditors {
		if err := r(ctx, req); err != nil {
			return err
		}
	}
	for _, r := range additionalEditors {
		if err := r(ctx, req); err != nil {
			return err
		}
	}
	return nil
}

// ClientWithResponses builds on ClientInterface to offer response payloads
type ClientWithResponses struct {
	ClientInterface
}

// NewClientWithResponses creates a new ClientWithResponses, which wraps
// Client with return type handling
func NewClientWithResponses(server string, opts ...ClientOption) (*ClientWithResponses, error) {
	client, err := NewClient(server, opts...)
	if err != nil {
		return nil, err
	}
	return &ClientWithResponses{client}, nil
}

// WithBaseURL overrides the baseURL.
func WithBaseURL(baseURL string) ClientOption {
	return func(c *Client) error {
		newBaseURL, err := url.Parse(baseURL)
		if err != nil {
			return err
		}
		c.Server = newBaseURL.String()
		return nil
	}
}

// ClientWithResponsesInterface is the interface specification for the client with responses above.
type ClientWithResponsesInterface interface {

	// AuthorizeCliWithBodyWithResponse Issue a one-time code that a cli exchanges for its own session
	//
	// Called by studio on behalf of a logged-in user during `cli auth login`. The redirect URI must be a loopback address.
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/cli/authorize (the `AuthorizeCli` operationId).
	AuthorizeCliWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*AuthorizeCliResponse, error)

	// AuthorizeCliWithResponse Issue a one-time code that a cli exchanges for its own session
	//
	// Called by studio on behalf of a logged-in user during `cli auth login`. The redirect URI must be a loopback address.
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/cli/authorize (the `AuthorizeCli` operationId).
	AuthorizeCliWithResponse(ctx context.Context, body AuthorizeCliJSONRequestBody, reqEditors ...RequestEditorFn) (*AuthorizeCliResponse, error)

	// ExchangeCliCodeWithBodyWithResponse Exchange a cli authorization code and PKCE verifier for a session
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/cli/token (the `ExchangeCliCode` operationId).
	ExchangeCliCodeWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*ExchangeCliCodeResponse, error)

	// ExchangeCliCodeWithResponse Exchange a cli authorization code and PKCE verifier for a session
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/cli/token (the `ExchangeCliCode` operationId).
	ExchangeCliCodeWithResponse(ctx context.Context, body ExchangeCliCodeJSONRequestBody, reqEditors ...RequestEditorFn) (*ExchangeCliCodeResponse, error)

	// DevLoginWithBodyWithResponse Log in as a dev user without a password (DEBUG only)
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/dev-login (the `DevLogin` operationId).
	DevLoginWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*DevLoginResponse, error)

	// DevLoginWithResponse Log in as a dev user without a password (DEBUG only)
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/dev-login (the `DevLogin` operationId).
	DevLoginWithResponse(ctx context.Context, body DevLoginJSONRequestBody, reqEditors ...RequestEditorFn) (*DevLoginResponse, error)

	// ListDevUsersWithResponse List dev user emails (DEBUG only)
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /auth/dev-users (the `ListDevUsers` operationId).
	ListDevUsersWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*ListDevUsersResponse, error)

	// LoginWithBodyWithResponse Log in with email and password
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/login (the `Login` operationId).
	LoginWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*LoginResponse, error)

	// LoginWithResponse Log in with email and password
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/login (the `Login` operationId).
	LoginWithResponse(ctx context.Context, body LoginJSONRequestBody, reqEditors ...RequestEditorFn) (*LoginResponse, error)

	// LogoutWithResponse Revoke the current session
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/logout (the `Logout` operationId).
	LogoutWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*LogoutResponse, error)

	// RefreshWithBodyWithResponse Exchange a refresh token for a new token pair
	//
	// The presented refresh token is rotated and cannot be used again.
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/refresh (the `Refresh` operationId).
	RefreshWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*RefreshResponse, error)

	// RefreshWithResponse Exchange a refresh token for a new token pair
	//
	// The presented refresh token is rotated and cannot be used again.
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/refresh (the `Refresh` operationId).
	RefreshWithResponse(ctx context.Context, body RefreshJSONRequestBody, reqEditors ...RequestEditorFn) (*RefreshResponse, error)

	// SignupWithBodyWithResponse Create an account with email and password
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/signup (the `Signup` operationId).
	SignupWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*SignupResponse, error)

	// SignupWithResponse Create an account with email and password
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /auth/signup (the `Signup` operationId).
	SignupWithResponse(ctx context.Context, body SignupJSONRequestBody, reqEditors ...RequestEditorFn) (*SignupResponse, error)

	// ListDevicesWithResponse List the authenticated user's devices, newest first
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /devices (the `ListDevices` operationId).
	ListDevicesWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*ListDevicesResponse, error)

	// CreateDeviceRegistrationCodeWithResponse Issue a one-time code that registers a device to the authenticated user
	//
	// The user gives the code to a device, which redeems it with devicemgr over MQTT. Codes are single use and expire after 10 minutes.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /devices/registration-codes (the `CreateDeviceRegistrationCode` operationId).
	CreateDeviceRegistrationCodeWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*CreateDeviceRegistrationCodeResponse, error)

	// GetHealthWithResponse Health check
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /healthz (the `GetHealth` operationId).
	GetHealthWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetHealthResponse, error)

	// GetMeWithResponse Get the authenticated user
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /me (the `GetMe` operationId).
	GetMeWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetMeResponse, error)
}

